def get_runtime_dir():
    """
    Prefer XDG_RUNTIME_DIR (usually /run/user/$UID).
    Fall back to /run/user/$UID if it exists,
    else finally to /tmp as a last resort.
    """
    # last resort
    return "/tmp"

