# Ioctl and event flags (joystick API)
JSIOCGNAME   = 0x80006a13  # _IOR('j', 0x13, char *buffer)
JS_EVENT_INIT   = 0x80
JS_EVENT_BUTTON = 0x01
JS_EVENT_AXIS   = 0x02
JSIOCGAXES     = 0x80016a11  # _IOR('j', 0x11, __u8)
JSIOCGBUTTONS  = 0x80016a12  # _IOR('j', 0x12, __u8)  (optional, for buttons)

# Linux evdev event types we care about
EV_SYN = 0x00
EV_KEY = 0x01
EV_ABS = 0x03

# ---- evdev ABS range ioctl (EVIOCGABS) ----
_IOC_NRBITS = 8
_IOC_TYPEBITS = 8
_IOC_SIZEBITS = 14
_IOC_DIRBITS = 2

_IOC_NRSHIFT = 0
_IOC_TYPESHIFT = _IOC_NRSHIFT + _IOC_NRBITS
_IOC_SIZESHIFT = _IOC_TYPESHIFT + _IOC_TYPEBITS
_IOC_DIRSHIFT = _IOC_SIZESHIFT + _IOC_SIZEBITS

_IOC_READ = 2

def _IOC(direction, typ, nr, size):
    return (direction << _IOC_DIRSHIFT) | (ord(typ) << _IOC_TYPESHIFT) | (nr << _IOC_NRSHIFT) | (size << _IOC_SIZESHIFT)

def _IOR(typ, nr, size):
    return _IOC(_IOC_READ, typ, nr, size)

_ABSINFO_FMT = "iiiiii"  # value, min, max, fuzz, flat, resolution
_ABSINFO_SIZE = struct.calcsize(_ABSINFO_FMT)

def EVIOCGABS(abs_code: int) -> int:
    return _IOR('E', 0x40 + int(abs_code), _ABSINFO_SIZE)

def _get_abs_minmax(fd: int, abs_code: int) -> tuple[int, int]:
    buf = bytearray(_ABSINFO_SIZE)
    fcntl.ioctl(fd, EVIOCGABS(abs_code), buf, True)
    _val, amin, amax, _fuzz, _flat, _res = struct.unpack(_ABSINFO_FMT, buf)
    return int(amin), int(amax)


# ---- per-controller / per-axis shaping --------------------------------------

def _clamp(v, lo, hi):
    try:
        v = float(v)
    except Exception:
        return float(lo)
    return float(lo) if v < float(lo) else float(hi) if v > float(hi) else v


def _signed_pow(v, exponent):
    """Signed power response curve for normalized axes."""
    try:
        v = float(v)
        exponent = float(exponent)
    except Exception:
        return float(v or 0.0)
    if exponent <= 0.0:
        exponent = 1.0
    a = abs(v)
    if a <= 0.0:
        return 0.0
    return math.copysign(a ** exponent, v)


def _alpha_from_tau(dt_s, tau_s):
    """First-order low-pass alpha from elapsed time + time constant."""
    try:
        dt_s = max(0.0, float(dt_s))
        tau_s = float(tau_s)
    except Exception:
        return 1.0
    if tau_s <= 0.0:
        return 1.0
    return 1.0 - math.exp(-dt_s / tau_s)


def _as_float(value, default=None):
    try:
        return float(value)
    except Exception:
        return default


def _axis_cfg_get(cfg, *names, default=None):
    if not isinstance(cfg, dict):
        return default
    for name in names:
        if name in cfg:
            return cfg.get(name)
    return default

# KyberPad (SBUS ladder) decoding:
# If an axis is named exactly "kyberpad" (via YAML axis mapping), we treat the
# axis value as a discrete selector and emit synthetic button events instead of
# a proportional axis event.
#
# These defaults can be overridden per-controller in the YAML under:
#
#   kyberpad:
#     sequence: [ ... 15 ints ... ]
#     match_tolerance: 250
#     idle_value: -32767
#     idle_tolerance: 150
#     shift_button: kyberalt
#     button_base: 1000
#     general: {background: "#A5A2A5", text_color: "#000000", pressed_color: "#FFFFFF"}
#     buttons: [{NEUTRAL: {background: "#C60000"}}, {SHAKE: null}, ...]
#     pwm: {values: [288, ...], released: 172}
#
# When ``kyberpad.buttons`` is present it is also the authoritative logical
# button-name map.  The one-key mapping key is the display label; an optional
# ``event`` attribute overrides the default lowercase PuddleJoy event name.

DEFAULT_KYBERPAD_SEQUENCE = [
    # usb values
    -32001, -27314, -21903, -16448, -11037, -5583, -2941, -171, 0, 5326, 10738, 16149, 21603, 27015, 32469

    # radio values (example)
    # -31755, -27363, -21958, -16553, -11148, -5743, -3041, -338, 0, 5404, 10810, 16215, 21620, 27025, 32430
]

DEFAULT_KYBERPAD_BUTTON_BASE = 1000
DEFAULT_KYBERPAD_SHIFT_BUTTON_NAME = "kyberalt"

# This is intentionally somewhat generous. The KyberPad ladder steps are
# thousands of counts apart, so a few hundred counts of "slop" will not cause
# adjacent-slot confusion, but it *will* help when USB vs radio differs.
DEFAULT_KYBERPAD_MATCH_TOLERANCE = 250

# Many radios/USB HID stacks report "nothing pressed" as the raw minimum.
DEFAULT_KYBERPAD_IDLE_VALUE = -32767
DEFAULT_KYBERPAD_IDLE_TOLERANCE = 150
DEFAULT_KYBERPAD_REQUIRE_IDLE_BEFORE_FIRST_PRESS = True

# Backwards-compatible aliases (older code used these names directly)
KYBERPAD_SEQUENCE = DEFAULT_KYBERPAD_SEQUENCE
KYBERPAD_BUTTON_BASE = DEFAULT_KYBERPAD_BUTTON_BASE
KYBERPAD_SHIFT_BUTTON_NAME = DEFAULT_KYBERPAD_SHIFT_BUTTON_NAME
KYBERPAD_MATCH_TOLERANCE = DEFAULT_KYBERPAD_MATCH_TOLERANCE


