# Registries
default_registry = {}
_controller_registry = {}
_controller_defs = {}
_controller_files = {}
_gesture_defs = {}

def register_controller(device_name):
    """Decorator to register a built-in controller class."""
    def decorator(cls):
        _controller_registry[device_name] = cls
        return cls
    return decorator


def load_controller_definitions(dir_path):
    """
    Load YAML files from dir_path to populate controller and gesture definitions.
    Expects:
      controllers:
        - device: 'Device Name'
          name: 'Friendly Name'
          buttons: {0: 'A', ...}  # for js devices: joystick indices
                                  # for event devices: evdev key codes (EV_KEY)
          axes: {0: 'LX', ...}    # for js devices: joystick indices
                                  # for event devices: evdev axis codes (EV_ABS)
          axis_curves:             # optional per logical axis
            head_yaw: {tau_s: 0.12, exponent: 1.2, deadzone: 0.02}
          invert_js_axes: true     # optional; Linux js* compatibility default
          gesture_trigger: 'LB'
          gestures:         # either dict or list
            Konami: ['U','U','D','D','L','R','L','R','B','A']
      gestures:
        - name: 'Konami'
          sequence: ['U','U','D','D','L','R','L','R','B','A']
          trigger: 'Select'
    """
    global _controller_defs, _gesture_defs

    cfg_dir = Path(dir_path)
    print(f"cfg_dir: {cfg_dir}")
    for file in cfg_dir.glob('*.yaml'):
        try:
            logger.info(f"Loading definitions from {file}")
            cfg = yaml.safe_load(file.read_text()) or {}
        except Exception as e:
            logger.error(f"Failed to load {file}: {e}")
            continue

        # Global gestures
        for g in cfg.get('gestures', []):
            name = g.get('name')
            seq  = g.get('sequence')
            trig = g.get('trigger')
            if name and isinstance(seq, list):
                _gesture_defs[name] = {'sequence': seq, 'trigger': trig}
                logger.debug(f"Registered gesture '{name}' -> {seq}")

        # Controllers
        source_devices = []
        for c in cfg.get('controllers', []):
            device = c.get('device')
            name   = c.get('name')
            btns   = {int(k): v for k, v in c.get('buttons', {}).items()}
            axes   = {int(k): v for k, v in c.get('axes', {}).items()}
            trigger = c.get('gesture_trigger')
            gestures = c.get('gestures', {})
            kyberpad = c.get('kyberpad')
            ros_topic = c.get('ros_topic')
            invert_js_axes = c.get('invert_js_axes', True)
            if not isinstance(invert_js_axes, bool):
                logger.warning(
                    f"Invalid invert_js_axes for controller {device!r} in {file}; "
                    "expected true or false. Using the compatibility default true."
                )
                invert_js_axes = True
            if kyberpad is not None:
                try:
                    validate_kyberpad(kyberpad)
                    btns = merge_synthetic_button_map(btns, kyberpad)
                except ValueError as exc:
                    logger.error(f"Invalid KyberPad definition for controller {device!r} in {file}: {exc}")
                    continue

            # Optional per-controller/per-axis shaping.  This deliberately lives
            # in PuddleJoy so different physical controllers can have different
            # deadzones, response curves, and low-pass smoothing without changing
            # DuckDrive.  Accepted aliases keep older/newer YAML names painless:
            #
            #   axis_curves:
            #     defaults: {deadzone: 0.02}
            #     head_yaw: {tau_s: 0.12, exponent: 1.4}
            #
            axis_curves = (
                c.get('axis_curves')
                or c.get('axis_filters')
                or c.get('axis_options')
                or {}
            )

            # Build gesture map
            gesture_map = {}
            if isinstance(gestures, list):
                # reference global gesture names
                for gname in gestures:
                    gd = _gesture_defs.get(gname)
                    if gd:
                        gesture_map[gname] = gd['sequence']
                    else:
                        logger.warning(f"Unknown gesture '{gname}' for controller '{device}'")
            elif isinstance(gestures, dict):
                for gname, seq in gestures.items():
                    if isinstance(seq, list):
                        gesture_map[gname] = seq
                    else:
                        logger.warning(f"Invalid sequence for gesture '{gname}' in {file}")

            _controller_defs[device] = {
                'name':             name,
                'buttons':          btns,
                'axes':             axes,
                'gesture_trigger':  trigger,
                'gestures':         gesture_map,
                'kyberpad':         kyberpad,
                'axis_curves':      axis_curves if isinstance(axis_curves, dict) else {},
                'invert_js_axes':   invert_js_axes,
                'ros_topic':        ros_topic,
                'source':           str(file),
            }
            if device not in source_devices:
                source_devices.append(device)
            logger.info(f"Controller '{device}' loaded: {name}")

        # A later file with the same basename (for example
        # $HOME/controllers/frsky.yaml) is the authoritative source for that
        # filename.  Replace rather than append so user overrides can also
        # change the controller's ``device`` identifier.
        _controller_files[file.name] = source_devices


def get_controller_definition(device_name):
    """Return one loaded controller definition as an independent mapping.

    Controller YAML is the authoritative source for physical button numbers,
    axis aliases, and sign inversion.  Returning a deep copy prevents a caller
    from accidentally mutating the global registry used by live controllers.
    """
    device_name = str(device_name)
    definition = _controller_defs.get(device_name)
    if definition is None:
        raise KeyError(f"No controller definition loaded for {device_name!r}")
    return copy.deepcopy(definition)


def get_controller_definition_for_file(filename, *, index=0):
    """Return a controller defined by a loaded YAML filename.

    This is useful for protocol adapters such as the body-side FrSky/SBUS
    bridge.  The built-in ``frsky.yaml`` identifies the physical wire mapping,
    while a user definition loaded later for the same device still overrides
    the values in the main registry.
    """
    source_name = Path(filename).name
    devices = _controller_files.get(source_name) or []
    try:
        device_name = devices[int(index)]
    except (IndexError, TypeError, ValueError):
        raise KeyError(
            f"No controller definition loaded from {source_name!r} at index {index}"
        )
    return get_controller_definition(device_name)


class ControllerEvent:
    """
    A single controller event, with optional gesture.
    """
    def __init__(self, controller, timestamp, value, event_type, number, gesture=None):
        self.controller = controller
        self.timestamp  = timestamp
        self.value      = value
        self.event_type = event_type
        self.number     = number
        self.gesture    = gesture
        self.initial    = False

        if event_type & JS_EVENT_BUTTON:
            self.name = controller.BUTTON_MAP.get(number, f'BTN{number}')
        elif event_type & JS_EVENT_AXIS:
            self.name = controller.AXIS_MAP.get(number, f'AXIS{number}')
        else:
            self.name = f'EVENT{number}'

    def is_button_event(self):
        return True if self.event_type & JS_EVENT_BUTTON else False

    def is_axis_event(self):
        return True if self.event_type & JS_EVENT_AXIS else False

    def is_pressed(self, button_name):
        """
        Continuous state: is this button currently held down?
        """
        return self.controller._buttons.get(button_name, False)

    def was_pressed(self, button_name):
        """
        Return True only on the button-down event for this button.
        For continuous state, use get_buttons() instead.
        """
        return (
            (self.event_type & JS_EVENT_BUTTON) and
            self.name == button_name and
            bool(self.value)   # pressed (non-zero), not release
        )

    def get_buttons(self):
        return [k for k,v in self.controller._buttons.items() if v]

    def get_axis(self, axis_name):
        # Controller owns scaling + optional per-axis shaping/filtering so callers
        # all see the same logical value.
        return self.controller.get_axis(axis_name)

    def get_axes(self):
        return {a: self.get_axis(a) for a in self.controller._axes}

    def __str__(self):
        parts = [f"[{self.timestamp}] {self.name} -> {self.value}"]
        if self.gesture:
            parts.append(f"Gesture: {self.gesture}")
        parts.append(f"Buttons: {self.get_buttons()}")
        parts.append(f"Axes: {self.get_axes()}")
        return " | ".join(parts)

    __repr__ = __str__


class Controller:
    """
    Base controller handling I/O, state, scaling, reconnections, and gestures.
    """
    BUTTON_MAP = {}
    AXIS_MAP   = {}

    def __init__(
        self,
        device_path,
        device_name,
        button_map,
        axis_map,
        reconnect_interval=1.0,
        *,
        kyberpad=None,
        axis_curves=None,
        invert_js_axes: bool = True,
        connect: bool = True,
    ):
        self.device_path         = device_path
        self.device_name         = device_name
        self.name                = device_name
        self.BUTTON_MAP          = button_map
        # The legacy Linux joystick API historically inverts every analog axis
        # before applying YAML sign prefixes. Real USB controllers keep that
        # compatibility default. Virtual controllers such as PuddleDuckStick
        # disable it so js*, evdev, FIFO, and shadow backends agree.
        self._invert_js_axes     = bool(invert_js_axes)
        self._axis_inverted      = set()

        # Axis mappings normally map one physical axis -> one logical name.
        # For mode-dependent controls, allow aliases by writing a YAML list, e.g.
        #   2: [lin_vel_y, posture_head_yaw]
        #   3: [height, -posture_head_pitch]
        # The first alias remains the event name; all aliases share the same raw
        # physical axis value and can have independent '-' inversion.
        self._axis_aliases      = {}
        cleaned_axis_map = {}
        for idx, name in axis_map.items():
            names = list(name) if isinstance(name, (list, tuple)) else [name]
            cleaned = []
            for item in names:
                if isinstance(item, str) and item.startswith('-'):
                    clean = item[1:]
                    self._axis_inverted.add(clean)
                else:
                    clean = item
                cleaned.append(clean)

            primary = cleaned[0] if cleaned else f'AXIS{idx}'
            cleaned_axis_map[idx] = primary
            self._axis_aliases[idx] = cleaned or [primary]
        self.AXIS_MAP = cleaned_axis_map
        self._reconnect_interval = reconnect_interval
        self.js                  = None
        self._last_reconnect     = 0.0

        # State
        self._buttons = {n: False for n in self.BUTTON_MAP.values()}
        axis_names = []
        for names in self._axis_aliases.values():
            axis_names.extend(names)
        self._axes    = {n: 0     for n in axis_names}

        # Scaling
        self._scales        = {}
        self._default_scale = None
        self._raw_min       = -32767
        self._raw_max       =  32767

        # Per-axis shaping/filtering configured from controller YAML.
        # Values are keyed by *logical* axis names after '-' inversion aliases
        # have been stripped (e.g. head_pitch, head_yaw, lin_vel_x).
        self._axis_curve_defaults = {}
        self._axis_curves = {}
        self._axis_filter_state = {}
        self.configure_axis_curves(axis_curves or {})

        # Gesture state
        self._gesture_trigger  = None
        self._gestures         = {}
        self._gesture_buttons  = set()
        self._gesture_max      = 0
        self._gesture_timeout  = 0
        self._gesture_start    = None
        self._gesture_buffer   = []
        self._ignore_releases  = []

        # Synthetic event queue (used for KyberPad axis->buttons, etc.)
        # Entries are tuples: (timestamp, value, event_type, number)
        self._pending_events = []

        # KyberPad current active button_id (1..30), or None if idle.
        # (This is WITHOUT the KYBERPAD_BUTTON_BASE offset.)
        self._kyberpad_active_button = None
        # Guard against startup/init values being interpreted as real presses.
        # The js API commonly reports initial axis state on open; on SBUS ladder
        # axes a centered/raw-zero init sample can coincide with a real button
        # slot.  We only allow a press after seeing an idle/no-button sample.
        self._kyberpad_seen_idle = False

        # KyberPad decoding configuration (can be overridden per-controller via YAML).
        self._kyberpad_sequence = list(DEFAULT_KYBERPAD_SEQUENCE)
        self._kyberpad_match_tolerance = int(DEFAULT_KYBERPAD_MATCH_TOLERANCE)
        self._kyberpad_idle_value = (
            int(DEFAULT_KYBERPAD_IDLE_VALUE)
            if DEFAULT_KYBERPAD_IDLE_VALUE is not None
            else None
        )
        self._kyberpad_idle_tolerance = int(DEFAULT_KYBERPAD_IDLE_TOLERANCE)
        self._kyberpad_require_idle_before_first_press = bool(DEFAULT_KYBERPAD_REQUIRE_IDLE_BEFORE_FIRST_PRESS)
        self._kyberpad_shift_button_name = str(DEFAULT_KYBERPAD_SHIFT_BUTTON_NAME)
        self._kyberpad_button_base = int(DEFAULT_KYBERPAD_BUTTON_BASE)
        # PuddleDuckStick receives KyberPad presses as already-decoded
        # BTN1001+ key events from the Teensy. It still uses kyberpad.buttons
        # as the logical mapping/export authority, but must not decode axis 6
        # again and emit duplicate presses.
        self._kyberpad_decode_axis = True
        self._apply_kyberpad_config(kyberpad)


        if connect:
            self._connect()


    def configure_axis_curves(self, axis_curves):
        """Configure per-axis logical shaping/filtering.

        YAML examples:

          axis_curves:
            defaults:
              deadzone: 0.02
            head_pitch:
              tau_s: 0.12
              exponent: 1.4
            head_yaw:
              tau_s: 0.10
              curve: 1.3

        Supported per-axis fields:
          deadzone / dz           zero small input; optional deadzone_rescale
          exponent / response_exponent / curve  signed power response
          gain / scale            multiply after curve
          offset                  add before deadzone
          min / max               output clamp, default [-1, 1]
          tau_s                   first-order smoothing time constant
          tau_up_s / tau_down_s   optional asymmetric smoothing by numeric direction
          tau_attack_s / tau_release_s optional asymmetric smoothing by abs(value)
        """
        self._axis_curve_defaults = {}
        self._axis_curves = {}
        self._axis_filter_state = {}

        if not isinstance(axis_curves, dict):
            return

        defaults = (
            axis_curves.get('defaults')
            or axis_curves.get('_defaults')
            or axis_curves.get('default')
            or {}
        )
        if isinstance(defaults, dict):
            self._axis_curve_defaults = dict(defaults)

        for name, cfg in axis_curves.items():
            if name in ('defaults', '_defaults', 'default'):
                continue
            if cfg is None:
                continue
            if isinstance(cfg, (int, float)):
                cfg = {'exponent': float(cfg)}
            if not isinstance(cfg, dict):
                logger.warning(
                    f"{self.device_name}: axis_curves.{name} must be a dict or number; "
                    f"got {type(cfg).__name__}. Ignoring."
                )
                continue
            self._axis_curves[str(name)] = dict(cfg)

    def _axis_curve_cfg(self, axis_name):
        cfg = {}
        if self._axis_curve_defaults:
            cfg.update(self._axis_curve_defaults)
        axis_cfg = self._axis_curves.get(str(axis_name))
        if axis_cfg:
            cfg.update(axis_cfg)
        return cfg

    def _get_axis_scaled(self, axis_name):
        """Raw device state -> logical scaled value, before per-axis curve/filter."""
        raw = self._axes.get(axis_name, 0)
        scale = self._scales.get(axis_name) or self._default_scale
        if scale:
            imin, imax, omin, omax = scale
            try:
                val = omin + (raw - imin) * (omax - omin) / (imax - imin)
            except ZeroDivisionError:
                val = raw
        else:
            val = raw

        if axis_name in getattr(self, "_axis_inverted", set()):
            val = -val

        try:
            return float(val)
        except Exception:
            return 0.0

    def _apply_axis_curve(self, axis_name, val, cfg):
        """Apply static shaping (offset, deadzone, exponent, gain, clamp)."""
        if not cfg:
            return float(val)

        offset = _as_float(_axis_cfg_get(cfg, 'offset', default=0.0), 0.0)
        val = float(val) + float(offset)

        # Clamp before shaping to avoid surprising power curves on out-of-range input.
        in_min = _as_float(_axis_cfg_get(cfg, 'input_min', 'in_min', default=-1.0), -1.0)
        in_max = _as_float(_axis_cfg_get(cfg, 'input_max', 'in_max', default=1.0), 1.0)
        val = _clamp(val, in_min, in_max)

        dz = _as_float(_axis_cfg_get(cfg, 'deadzone', 'dz', default=0.0), 0.0)
        dz = _clamp(dz, 0.0, 0.999)
        if dz > 0.0:
            a = abs(val)
            if a < dz:
                val = 0.0
            elif bool(_axis_cfg_get(cfg, 'deadzone_rescale', 'rescale_deadzone', default=False)):
                # Optional: preserve full outer range after removing center deadzone.
                val = math.copysign((a - dz) / max(1e-9, 1.0 - dz), val)

        exponent = _axis_cfg_get(cfg, 'exponent', 'response_exponent', 'expo', 'curve', default=1.0)
        # Allow curve: {exponent: ...} too.
        if isinstance(exponent, dict):
            exponent = _axis_cfg_get(exponent, 'exponent', 'response_exponent', 'expo', default=1.0)
        exponent = _as_float(exponent, 1.0)
        if exponent is None or exponent <= 0.0:
            exponent = 1.0
        if abs(exponent - 1.0) > 1e-9:
            val = _signed_pow(val, exponent)

        gain = _as_float(_axis_cfg_get(cfg, 'gain', 'scale', default=1.0), 1.0)
        val *= float(gain)

        out_min = _as_float(_axis_cfg_get(cfg, 'min', 'out_min', 'output_min', default=-1.0), -1.0)
        out_max = _as_float(_axis_cfg_get(cfg, 'max', 'out_max', 'output_max', default=1.0), 1.0)
        if out_min > out_max:
            out_min, out_max = out_max, out_min
        return _clamp(val, out_min, out_max)

    def _filter_axis_value(self, axis_name, target, cfg):
        """Apply optional time-based smoothing after static shaping."""
        if not cfg:
            return float(target)

        # Default symmetric tau, with optional asymmetric overrides.
        tau = _as_float(_axis_cfg_get(cfg, 'tau_s', 'smooth_tau_s', 'smoothing_tau_s', default=0.0), 0.0)
        now = time.monotonic()
        st = self._axis_filter_state.get(axis_name)
        prev = float(st.get('value', target)) if isinstance(st, dict) else float(target)

        # Direction-specific tau by numeric direction.
        if float(target) > prev:
            tau = _as_float(_axis_cfg_get(cfg, 'tau_up_s', default=tau), tau)
        elif float(target) < prev:
            tau = _as_float(_axis_cfg_get(cfg, 'tau_down_s', default=tau), tau)

        # Attack/release tau by magnitude, useful for sticks that should respond
        # quickly away from center but drift back slowly.
        if abs(float(target)) > abs(prev):
            tau = _as_float(_axis_cfg_get(cfg, 'tau_attack_s', default=tau), tau)
        elif abs(float(target)) < abs(prev):
            tau = _as_float(_axis_cfg_get(cfg, 'tau_release_s', default=tau), tau)

        if tau is None or tau <= 0.0:
            self._axis_filter_state[axis_name] = {'value': float(target), 't': now}
            return float(target)

        if st is None:
            # First read should not slew from zero unless explicitly requested.
            init_to_target = bool(_axis_cfg_get(cfg, 'init_to_target', 'snap_on_first', default=True))
            initial = float(target) if init_to_target else 0.0
            self._axis_filter_state[axis_name] = {'value': initial, 't': now}
            return initial

        dt = max(0.0, now - float(st.get('t', now)))
        # Optional dt cap prevents a long pause from turning into a full snap.
        dt_cap = _as_float(_axis_cfg_get(cfg, 'dt_cap_s', default=None), None)
        if dt_cap is not None and dt_cap > 0.0:
            dt = min(dt, float(dt_cap))

        alpha = _alpha_from_tau(dt, tau)
        value = prev * (1.0 - alpha) + float(target) * alpha

        eps = _as_float(_axis_cfg_get(cfg, 'eps', 'zero_eps', default=0.0), 0.0)
        if eps and abs(value) < eps:
            value = 0.0

        self._axis_filter_state[axis_name] = {'value': float(value), 't': now}
        return float(value)

    def get_axis(self, axis_name):
        """Return a logical axis value after scaling, inversion, curve, and smoothing."""
        axis_name = str(axis_name)
        val = self._get_axis_scaled(axis_name)
        cfg = self._axis_curve_cfg(axis_name)
        if cfg:
            val = self._apply_axis_curve(axis_name, val, cfg)
            val = self._filter_axis_value(axis_name, val, cfg)
        return val

    def _apply_kyberpad_config(self, kyberpad):
        """Apply per-controller KyberPad overrides from YAML."""
        if not kyberpad:
            return
        if not isinstance(kyberpad, dict):
            logger.warning(
                f"{self.device_name}: kyberpad config must be a dict; got {type(kyberpad).__name__}. Ignoring."
            )
            return

        seq = kyberpad.get('sequence')
        if seq is not None:
            if isinstance(seq, list) and seq:
                try:
                    self._kyberpad_sequence = [int(x) for x in seq]
                except Exception:
                    logger.warning(
                        f"{self.device_name}: invalid kyberpad.sequence; expected list of ints. Using defaults."
                    )
            else:
                logger.warning(
                    f"{self.device_name}: kyberpad.sequence must be a non-empty list. Using defaults."
                )

        if 'match_tolerance' in kyberpad:
            try:
                self._kyberpad_match_tolerance = int(kyberpad.get('match_tolerance'))
            except Exception:
                logger.warning(
                    f"{self.device_name}: invalid kyberpad.match_tolerance; expected int. Using defaults."
                )

        if 'idle_value' in kyberpad:
            try:
                v = kyberpad.get('idle_value')
                self._kyberpad_idle_value = None if v is None else int(v)
            except Exception:
                logger.warning(
                    f"{self.device_name}: invalid kyberpad.idle_value; expected int or null. Using defaults."
                )

        if 'idle_tolerance' in kyberpad:
            try:
                self._kyberpad_idle_tolerance = int(kyberpad.get('idle_tolerance'))
            except Exception:
                logger.warning(
                    f"{self.device_name}: invalid kyberpad.idle_tolerance; expected int. Using defaults."
                )

        for key in ('require_idle_before_first_press', 'require_idle_before_press'):
            if key in kyberpad:
                try:
                    self._kyberpad_require_idle_before_first_press = bool(kyberpad.get(key))
                except Exception:
                    logger.warning(
                        f"{self.device_name}: invalid kyberpad.{key}; expected bool. Using defaults."
                    )
                break

        if 'shift_button' in kyberpad:
            try:
                self._kyberpad_shift_button_name = str(kyberpad.get('shift_button'))
            except Exception:
                logger.warning(
                    f"{self.device_name}: invalid kyberpad.shift_button; expected string. Using defaults."
                )

        if 'button_base' in kyberpad:
            try:
                self._kyberpad_button_base = int(kyberpad.get('button_base'))
            except Exception:
                logger.warning(
                    f"{self.device_name}: invalid kyberpad.button_base; expected int. Using defaults."
                )

        if 'decode_axis' in kyberpad:
            value = kyberpad.get('decode_axis')
            if isinstance(value, bool):
                self._kyberpad_decode_axis = value
            else:
                logger.warning(
                    f"{self.device_name}: invalid kyberpad.decode_axis; expected bool. Using defaults."
                )

    def _connect(self):
        if Path(self.device_path).exists():
            try:
                self.js   = open(self.device_path, 'rb')
                self.name = self._get_name()
                # A new fd will usually replay initial axis state. Reset the
                # KyberPad arm state so those init samples cannot look like
                # fresh synthetic button presses.
                self._kyberpad_active_button = None
                self._kyberpad_seen_idle = False
                logger.info(f"Connected to {self.name} ({self.device_path})")
                self.report_mapping_gaps()
            except Exception as e:
                logger.error(f"Cannot open {self.device_path}: {e}")
                self.js = None
        else:
            self.js = None

    def report_mapping_gaps(self):
        """Log any unmapped or out-of-range axis/button indices for this device."""
        try:
            n_axes = self._get_axes_counts()
        except Exception as e:
            logger.debug(f"Failed to query axis count for {self.device_path}: {e}")
            n_axes = None

        try:
            n_btns = self._get_button_counts()
        except Exception as e:
            logger.debug(f"Failed to query button count for {self.device_path}: {e}")
            n_btns = None

        if n_axes is not None:
            device_axis_idxs = set(range(n_axes))
            mapped_axis_idxs = set(self.AXIS_MAP.keys())
            unmapped_axes = sorted(device_axis_idxs - mapped_axis_idxs)
            extra_axis_mappings = sorted(mapped_axis_idxs - device_axis_idxs)
            if unmapped_axes:
                logger.warning(
                    f"{self.name}: unmapped axis indices: {unmapped_axes} "
                    f"(have {n_axes} axes; mapped: {sorted(mapped_axis_idxs)})"
                )
            if extra_axis_mappings:
                logger.warning(
                    f"{self.name}: axis mappings refer to non-existent indices: {extra_axis_mappings} "
                    f"(device has {n_axes} axes)"
                )

        if n_btns is not None:
            device_btn_idxs = set(range(n_btns))
            # BUTTON_MAP may include synthetic button numbers (e.g., KyberPad buttons at 1000+).
            # Exclude those from "mapping gap" diagnostics against the physical device button count.
            mapped_btn_idxs = {i for i in self.BUTTON_MAP.keys() if i < self._kyberpad_button_base}
            unmapped_btns = sorted(device_btn_idxs - mapped_btn_idxs)
            extra_button_mappings = sorted(mapped_btn_idxs - device_btn_idxs)
            if unmapped_btns:
                logger.warning(
                    f"{self.name}: unmapped button indices: {unmapped_btns} "
                    f"(have {n_btns} buttons; mapped: {sorted(mapped_btn_idxs)})"
                )
            if extra_button_mappings:
                logger.warning(
                    f"{self.name}: button mappings refer to non-existent indices: {extra_button_mappings} "
                    f"(device has {n_btns} buttons)"
                )

    def is_connected(self):
        return self.js is not None and Path(self.device_path).exists()

    def _try_reconnect(self):
        now = time.time()
        if not self.is_connected() and now - self._last_reconnect >= self._reconnect_interval:
            logger.info(f"Attemping to reconnect {getattr(self, 'name', self.device_name)}")
            self._last_reconnect = now
            self._connect()

    def _get_axes_counts(self):
        abuf = array.array('B', [0])
        fcntl.ioctl(self.js, JSIOCGAXES, abuf)
        return abuf[0]

    def _get_button_counts(self):
        bbuf = array.array('B', [0])
        fcntl.ioctl(self.js, JSIOCGBUTTONS, bbuf)
        return bbuf[0]

    def _get_name(self):
        buf = array.array('b', [0]*128)
        fcntl.ioctl(self.js, JSIOCGNAME + (len(buf)<<16), buf)
        return buf.tobytes().rstrip(b'\x00').decode('utf-8', 'replace')

    def set_scale(self, out_min, out_max, in_min=None, in_max=None, axis=None):
        in_min = in_min if in_min is not None else self._raw_min
        in_max = in_max if in_max is not None else self._raw_max
        if axis:
            self._scales[axis] = (in_min, in_max, out_min, out_max)
        else:
            self._default_scale = (in_min, in_max, out_min, out_max)

    def configure_gestures(
        self,
        trigger_button,
        gesture_map,
        gesture_buttons=None,
        max_presses=10,
        timeout_ms=2000
    ):
        """
        Configure gesture recognition:
          - trigger_button: starts capture when pressed
          - gesture_map: {name: [sequence]}
          - gesture_buttons: optional allowed buttons; defaults to all in sequences
          - max_presses: max seq length
          - timeout_ms: capture window in ms
        """
        self._gesture_trigger = trigger_button
        self._gestures        = gesture_map
        self._gesture_max     = max_presses
        self._gesture_timeout = timeout_ms / 1000.0
        # Derive allowed buttons if not explicitly given
        if gesture_buttons:
            self._gesture_buttons = set(gesture_buttons)
        else:
            # flatten all gesture sequences
            self._gesture_buttons = set().union(*gesture_map.values())
        self._gesture_buffer  = []
        self._gesture_start   = None
        self._ignore_releases = []
        logger.info(f"Gestures configured: trigger={trigger_button}, map={gesture_map}")

    def _update_gesture(self, event):
        now = time.time()
        # Start capture
        if event.name == self._gesture_trigger and event.value:
            self._gesture_start  = now
            self._gesture_buffer = []
            return None

        # Only button-down
        if not (event.event_type & JS_EVENT_BUTTON and event.value):
            return None

        # Outside window
        if self._gesture_start is None or now - self._gesture_start > self._gesture_timeout:
            self._gesture_start  = None
            self._gesture_buffer = []
            return None

        # Abort on disallowed button
        if event.name not in self._gesture_buttons:
            self._gesture_start  = None
            self._gesture_buffer = []
            return None

        # Record
        self._gesture_buffer.append(event.name)
        self._gesture_start = now  # extend timeout

        # Check valid prefixes
        valid = any(seq[:len(self._gesture_buffer)] == self._gesture_buffer
                    for seq in self._gestures.values())
        if not valid:
            self._gesture_start  = None
            self._gesture_buffer = []
            return None

        # Full match?
        for name, seq in self._gestures.items():
            if self._gesture_buffer == seq:
                self._gesture_start  = None
                self._gesture_buffer = []
                self._ignore_releases = list(seq)
                return name

        # Reset if too long
        if len(self._gesture_buffer) >= self._gesture_max:
            self._gesture_start  = None
            self._gesture_buffer = []
        return None


    # ---------------------------------------------------------------------
    # Synthetic events (KyberPad axis -> buttons)
    # ---------------------------------------------------------------------
    def _enqueue_synthetic(self, timestamp: int, value: int, event_type: int, number: int):
        self._pending_events.append((timestamp, value, event_type, number))

    def _drain_pending(self, invert_axes: bool):
        """Return the next pending synthetic event (after running gesture logic), or None."""
        while self._pending_events:
            ts, val, etype, num = self._pending_events.pop(0)
            ev = self._dispatch_event(ts, val, etype, num, invert_axes=invert_axes)
            if ev is not None:
                return ev
        return None

    def _kyberpad_shift_active(self) -> bool:
        return self._buttons.get(self._kyberpad_shift_button_name, False)

    def _decode_kyberpad_button(self, raw_value):
        """Return 1..len(sequence) if raw_value matches a KyberPad slot, else None."""
        # Treat the configured "idle" value as no-button.
        # Many radios/USB HID stacks report idle as the raw minimum (-32767).
        if self._kyberpad_idle_value is not None:
            try:
                if abs(raw_value - int(self._kyberpad_idle_value)) <= int(self._kyberpad_idle_tolerance):
                    return None
            except Exception:
                # If the config is malformed, fall back to sequence matching.
                pass

        seq = self._kyberpad_sequence or []
        if not seq:
            return None

        best_i = None
        best_d = None
        for i, s in enumerate(seq):
            d = abs(raw_value - s)
            if best_d is None or d < best_d:
                best_d = d
                best_i = i

        if best_d is not None and best_d <= self._kyberpad_match_tolerance:
            return best_i + 1  # 1-based
        return None

    def _emit_kyberpad_transition(self, timestamp: int, new_button_id):
        """
        new_button_id is 1..30 (without KYBERPAD_BUTTON_BASE) or None.
        Enqueues release/press events as needed.
        """
        old = self._kyberpad_active_button
        if new_button_id == old:
            return

        # Release old
        if old is not None:
            self._enqueue_synthetic(
                timestamp=timestamp,
                value=0,
                event_type=JS_EVENT_BUTTON,
                number=self._kyberpad_button_base + int(old),
            )

        # Press new
        if new_button_id is not None:
            self._enqueue_synthetic(
                timestamp=timestamp,
                value=1,
                event_type=JS_EVENT_BUTTON,
                number=self._kyberpad_button_base + int(new_button_id),
            )

        self._kyberpad_active_button = new_button_id

    def _handle_kyberpad_axis(self, timestamp: int, raw_value, *, from_init: bool = False):
        """Consume a kyberpad axis update and enqueue synthetic button events.

        Controllers with ``kyberpad.decode_axis: false`` receive BTN1001+ key
        events from another decoder (the PuddleDuck Teensy for PuddleDuckStick),
        so the raw ladder axis is state-only.

        Startup/init axis samples are state only. They must not synthesize a
        press because a raw startup value can equal a valid ladder slot. Also
        require one idle/no-button sample after connect before the first press,
        so a non-init startup blip cannot latch a mode such as /antenna/scared.
        """
        if not bool(getattr(self, "_kyberpad_decode_axis", True)):
            return

        slot = self._decode_kyberpad_button(raw_value)  # 1..15 or None

        if slot is None:
            self._kyberpad_seen_idle = True
            if from_init:
                self._kyberpad_active_button = None
            else:
                self._emit_kyberpad_transition(timestamp, None)
            return

        if from_init:
            # Seed only. Do not treat joystick init state as a user press.
            self._kyberpad_active_button = None
            return

        if (
            bool(getattr(self, "_kyberpad_require_idle_before_first_press", True))
            and not bool(getattr(self, "_kyberpad_seen_idle", False))
        ):
            # Ignore the first non-idle value after connect until we have seen
            # an explicit idle sample. This prevents startup raw-zero samples
            # from latching real actions.
            return

        bank = 15 if self._kyberpad_shift_active() else 0
        button_id = slot + bank  # 1..30
        self._emit_kyberpad_transition(timestamp, button_id)

    def _dispatch_event(self, timestamp, value, event_type, number, *, invert_axes: bool):
        """
        Shared event pipeline:
          - update internal state (buttons/axes)
          - gesture detection / suppression
          - build and return ControllerEvent (or None if suppressed)
        """
        # Map to names + update state
        if event_type & JS_EVENT_BUTTON:
            name = self.BUTTON_MAP.get(number, f'BTN{number}')
            self._buttons[name] = bool(value)
        elif event_type & JS_EVENT_AXIS:
            name = self.AXIS_MAP.get(number, f'AXIS{number}')
            aliases = list(getattr(self, "_axis_aliases", {}).get(number, [name]))
            for alias in aliases:
                # For any kyberpad-related axis, keep raw values (no inversion).
                if isinstance(alias, str) and alias.lower().startswith("kyberpad"):
                    self._axes[alias] = value
                else:
                    self._axes[alias] = (-value if invert_axes else value)
        else:
            name = f'EV{number}'

        # Ignore release if part of gesture
        if event_type & JS_EVENT_BUTTON and value == 0 and name in self._ignore_releases:
            self._ignore_releases.remove(name)
            return None

        # Create event
        event = ControllerEvent(self, timestamp, value, event_type, number)

        gesture = None
        if self._gesture_trigger and event_type & JS_EVENT_BUTTON:
            gesture = self._update_gesture(event)
        event.gesture = gesture

        # If gesture detected, return gesture event only
        if gesture and event_type & JS_EVENT_BUTTON:
            event.name  = gesture
            event.value = None
            return event

        # Suppress button events during capture
        if self._gesture_start:
            return None

        return event

    def read_event(self, blocking=True):
        # Emit any queued synthetic events first (e.g., KyberPad axis->buttons).
        pending = self._drain_pending(invert_axes=self._invert_js_axes)
        if pending is not None:
            return pending

        # Reconnect logic
        if not self.is_connected():
            if self.js:
                self.disconnected()
            self._try_reconnect()
            if not self.is_connected():
                return None

        fd = self.js.fileno()
        if not blocking:
            # Use non-block instead of select or we will miss events
            # due to driver buffering
            fl = fcntl.fcntl(fd, fcntl.F_GETFL)
            fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)

        try:
            ev_size = struct.calcsize('IhBB')
            buf = self.js.read(ev_size)
        except BlockingIOError:
            return None  # No data yet
        except OSError:
            self.disconnected()
            return None
        finally:
            if not blocking:
                fcntl.fcntl(fd, fcntl.F_SETFL, fl)

        if not buf or len(buf) < ev_size:
            return None

        timestamp, value, event_type, number = struct.unpack('IhBB', buf)

        # Linux joystick devices emit JS_EVENT_INIT records when a device is
        # opened. Those records are useful for seeding normal analog axes, but
        # a KyberPad/SBUS ladder value of 0 is also a valid button slot. If we
        # decode init records as real KyberPad presses, simply starting with
        # ``-j`` can synthesize e.g. /antenna/scared and latch the antenna show
        # state before the operator touches the pad.
        is_init = bool(event_type & JS_EVENT_INIT)
        event_type &= ~JS_EVENT_INIT   # remove init flag so we can treat it normally

        # KyberPad: axis named exactly "kyberpad" becomes synthetic button events.
        if event_type & JS_EVENT_AXIS:
            axis_name = self.AXIS_MAP.get(number, f'AXIS{number}')
            aliases = list(getattr(self, "_axis_aliases", {}).get(number, [axis_name]))
            if any(isinstance(a, str) and a.lower() == "kyberpad" for a in aliases):
                # Keep the raw value (no inversion) for kyberpad decoding.
                for alias in aliases:
                    if isinstance(alias, str) and alias.lower() == "kyberpad":
                        self._axes[alias] = value

                self._handle_kyberpad_axis(timestamp, value, from_init=is_init)
                if is_init:
                    return None
                return self._drain_pending(invert_axes=self._invert_js_axes)

        event = self._dispatch_event(timestamp, value, event_type, number, invert_axes=self._invert_js_axes)
        if event is not None:
            event.initial = bool(is_init)
        return event

    def disconnected(self):
        if self.js:
            logger.info(f"Controller disconnected {getattr(self, 'name', self.device_name)}")
            self.close()

    def close(self):
        if self.js:
            self.js.close()
            self.js = None


def _get_event_device_name(dev_path: str) -> str:
    """
    Try to read the friendly name for an /dev/input/eventX device
    via /sys/class/input/eventX/device/name. Fallback to path.
    """
    p = Path(dev_path)
    name_file = Path("/sys/class/input") / p.name / "device" / "name"
    try:
        return name_file.read_text(encoding="utf-8").strip()
    except Exception:
        return str(p)


class EventController(Controller):
    """
    Controller that reads from /dev/input/event* using the Linux evdev
    input_event structure.

    For this controller, BUTTON_MAP/AXIS_MAP keys must be evdev codes:
      - EV_KEY codes for buttons
      - EV_ABS codes for axes
    """
    def __init__(
        self,
        device_path,
        device_name,
        button_map,
        axis_map,
        reconnect_interval=1.0,
        *,
        kyberpad=None,
        axis_curves=None,
        connect: bool = True,
    ):
        super().__init__(
            device_path=device_path,
            device_name=device_name,
            button_map=button_map,
            axis_map=axis_map,
            reconnect_interval=reconnect_interval,
            kyberpad=kyberpad,
            axis_curves=axis_curves,
            connect=connect,
        )
        self._raw_min = -32767
        self._raw_max = 32767
        self._configure_abs_scales()

    def _connect(self):
        super()._connect()
        self._configure_abs_scales()

    def _configure_abs_scales(self):
        if not self.js:
            return
        fd = self.js.fileno()

        for code, axis_name in self.AXIS_MAP.items():
            aliases = list(getattr(self, "_axis_aliases", {}).get(code, [axis_name]))

            # Don't mess with kyberpad raw ladder values. If any alias for this
            # physical axis is kyberpad, keep that raw path untouched, but still
            # scale any non-kyberpad aliases on the same axis.
            non_kyber_aliases = [
                a for a in aliases
                if not (isinstance(a, str) and a.lower() == "kyberpad")
            ]
            if not non_kyber_aliases:
                continue

            try:
                amin, amax = _get_abs_minmax(fd, int(code))
            except Exception:
                continue

            # Map that physical axis' native range -> [-1, 1] for every logical
            # alias.  Without this, secondary aliases on evdev controllers would
            # bypass the ABS min/max scaling and arrive as raw counts.
            for alias in non_kyber_aliases:
                self.set_scale(-1.0, 1.0, in_min=amin, in_max=amax, axis=alias)

    def _get_name(self):
        # Use sysfs name instead of joystick ioctl
        return _get_event_device_name(self.device_path)

    def _get_axes_counts(self):
        # Not trivial via ioctls here; we just skip mapping-gap checks
        raise RuntimeError("axis counts not supported for event devices")

    def _get_button_counts(self):
        raise RuntimeError("button counts not supported for event devices")

    def read_event(self, blocking=True):
        # Emit any queued synthetic events first (e.g., KyberPad axis->buttons).
        pending = self._drain_pending(invert_axes=False)
        if pending is not None:
            return pending

        # Reconnect logic (same as base)
        if not self.is_connected():
            if self.js:
                self.disconnected()
            self._try_reconnect()
            if not self.is_connected():
                return None

        fd = self.js.fileno()
        if not blocking:
            fl = fcntl.fcntl(fd, fcntl.F_GETFL)
            fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)

        try:
            # struct input_event {
            #   struct timeval time;  (long, long)
            #   __u16 type;
            #   __u16 code;
            #   __s32 value;
            # }
            ev_size = struct.calcsize("llHHI")
            buf = self.js.read(ev_size)
        except BlockingIOError:
            return None
        except OSError:
            self.disconnected()
            return None
        finally:
            if not blocking:
                fcntl.fcntl(fd, fcntl.F_SETFL, fl)

        if not buf or len(buf) < ev_size:
            return None

        sec, usec, etype, code, value = struct.unpack("llHHi", buf)
        # Approximate timestamp in milliseconds to fit your existing representation
        timestamp = int(sec * 1000 + usec / 1000)

        if etype == EV_KEY:
            event_type = JS_EVENT_BUTTON
            number = code
        elif etype == EV_ABS:
            event_type = JS_EVENT_AXIS
            number = code
        else:
            # Ignore other event types
            return None

        # KyberPad: axis named exactly "kyberpad" becomes synthetic button events.
        if event_type & JS_EVENT_AXIS:
            axis_name = self.AXIS_MAP.get(number, f'AXIS{number}')
            aliases = list(getattr(self, "_axis_aliases", {}).get(number, [axis_name]))
            if any(isinstance(a, str) and a.lower() == "kyberpad" for a in aliases):
                # Store raw value for kyberpad decoding.
                for alias in aliases:
                    if isinstance(alias, str) and alias.lower() == "kyberpad":
                        self._axes[alias] = value
                self._handle_kyberpad_axis(timestamp, value)
                return self._drain_pending(invert_axes=False)

        return self._dispatch_event(timestamp, value, event_type, number, invert_axes=False)

class PipeController(EventController):
    """Controller backed by an evdev-style named FIFO.

    This intentionally keeps the same one-input_event-per-read behavior as
    EventController.  A previous batch/coalescing reader helped expose FIFO
    backlog, but it also did too much work inside a single RLWalk controller
    poll and made joystick motion feel laggy.  Keep the hot path simple and
    add only low-overhead counters/traces so we can see whether the pipe is
    filling, disconnecting, or returning only SYN/ignored records.
    """

    def __init__(self, *args, **kwargs):
        self._pipe_stats = {
            "calls": 0,
            "records": 0,
            "returned": 0,
            "none": 0,
            "would_block": 0,
            "empty": 0,
            "short": 0,
            "syn": 0,
            "ignored": 0,
            "disconnects": 0,
            "errors": 0,
            "max_avail": 0,
            "last_etype": -1,
            "last_code": -1,
            "last_value": 0,
        }
        self._pipe_last_trace_t = 0.0
        self._pipe_trace_enabled = (os.environ.get("PUDDLEDUCK_PIPE_TRACE", "1").lower() not in ("0", "false", "no", "off"))
        try:
            self._pipe_trace_interval_s = max(0.1, float(os.environ.get("PUDDLEDUCK_PIPE_TRACE_INTERVAL", "2.0")))
        except Exception:
            self._pipe_trace_interval_s = 2.0
        try:
            self._pipe_warn_events = max(1, int(os.environ.get("PUDDLEDUCK_PIPE_WARN_EVENTS", "128")))
        except Exception:
            self._pipe_warn_events = 128
        super().__init__(*args, **kwargs)

    def _connect(self):
        path = Path(self.device_path)

        if not path.exists():
            self.js = None
            return

        try:
            st = os.stat(self.device_path)
            if not stat.S_ISFIFO(st.st_mode):
                logger.error(f"{self.device_path} exists but is not a FIFO")
                self.js = None
                return

            # Important:
            # A normal open(path, "rb") blocks on FIFOs until a writer appears.
            # O_RDWR | O_NONBLOCK is Linux-friendly and prevents discovery hangs.
            fd = os.open(self.device_path, os.O_RDWR | os.O_NONBLOCK)
            self.js = os.fdopen(fd, "rb", buffering=0)

            self.name = self._get_name()

            # Match base Controller._connect() side effects.
            self._kyberpad_active_button = None
            self._kyberpad_seen_idle = False

            logger.info(f"Connected to {self.name} ({self.device_path})")
            self._pipe_trace("connected", force=True)
            self.report_mapping_gaps()

        except Exception as e:
            logger.error(f"Cannot open FIFO {self.device_path}: {e}")
            self.js = None

    def _get_name(self):
        # No sysfs; return the logical device name so logs distinguish
        # PuddleDuckStick from SteamDuckStick.
        return self.device_name or self.device_path

    def _get_axes_counts(self):
        return 32

    def _get_button_counts(self):
        return 32

    def _fifo_bytes_available(self, fd: int):
        try:
            packed = fcntl.ioctl(fd, termios.FIONREAD, struct.pack("I", 0))
            return int(struct.unpack("I", packed[:4])[0])
        except Exception:
            return None

    def _pipe_trace(self, reason: str, *, avail=None, force: bool = False):
        if not self._pipe_trace_enabled and not force:
            return
        now = time.time()
        if not force and (now - self._pipe_last_trace_t) < self._pipe_trace_interval_s:
            return
        self._pipe_last_trace_t = now
        ev_size = struct.calcsize("llHHi")
        logger.info(
            "PIPE_TRACE device=%r reason=%s path=%r fd=%s avail_bytes=%s avail_events=%s "
            "calls=%s records=%s returned=%s none=%s would_block=%s empty=%s short=%s "
            "syn=%s ignored=%s max_avail=%s disconnects=%s errors=%s "
            "last=(etype:%s code:%s value:%s)",
            self.device_name,
            reason,
            self.device_path,
            "open" if self.js is not None else "closed",
            avail,
            (None if avail is None else int(avail) // ev_size),
            self._pipe_stats["calls"],
            self._pipe_stats["records"],
            self._pipe_stats["returned"],
            self._pipe_stats["none"],
            self._pipe_stats["would_block"],
            self._pipe_stats["empty"],
            self._pipe_stats["short"],
            self._pipe_stats["syn"],
            self._pipe_stats["ignored"],
            self._pipe_stats["max_avail"],
            self._pipe_stats["disconnects"],
            self._pipe_stats["errors"],
            self._pipe_stats["last_etype"],
            self._pipe_stats["last_code"],
            self._pipe_stats["last_value"],
        )

    def _maybe_trace_backlog(self, fd: int):
        if not self._pipe_trace_enabled:
            return
        now = time.time()
        if (now - self._pipe_last_trace_t) < self._pipe_trace_interval_s:
            return
        ev_size = struct.calcsize("llHHi")
        avail = self._fifo_bytes_available(fd)
        if avail is not None:
            self._pipe_stats["max_avail"] = max(int(avail), int(self._pipe_stats["max_avail"]))
            if int(avail) >= ev_size * int(self._pipe_warn_events):
                self._pipe_trace("backlog", avail=avail)

    def _return_event(self, ev):
        if ev is None:
            self._pipe_stats["none"] += 1
            return None
        self._pipe_stats["returned"] += 1
        return ev

    def read_event(self, blocking=True):
        """Read exactly one raw FIFO event per call, like EventController.

        This restores the pre-instrumentation responsiveness.  Do not drain or
        coalesce here; DuckDrive/RLWalk already controls how many events to poll
        per update with max_events_per_update.
        """
        self._pipe_stats["calls"] += 1

        # Emit any queued synthetic events first (e.g., KyberPad axis->buttons).
        pending = self._drain_pending(invert_axes=False)
        if pending is not None:
            return self._return_event(pending)

        # Reconnect logic (same as EventController).
        if not self.is_connected():
            if self.js:
                self.disconnected()
            self._try_reconnect()
            if not self.is_connected():
                return self._return_event(None)

        fd = self.js.fileno()
        self._maybe_trace_backlog(fd)

        if not blocking:
            fl = fcntl.fcntl(fd, fcntl.F_GETFL)
            fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)

        ev_size = struct.calcsize("llHHi")
        try:
            # struct input_event {
            #   struct timeval time;  (long, long)
            #   __u16 type;
            #   __u16 code;
            #   __s32 value;
            # }
            buf = self.js.read(ev_size)
        except BlockingIOError:
            self._pipe_stats["would_block"] += 1
            return self._return_event(None)
        except OSError as e:
            self._pipe_stats["errors"] += 1
            self._pipe_stats["disconnects"] += 1
            self._pipe_trace(f"read_error:{getattr(e, 'errno', 0)}", force=True)
            self.disconnected()
            return self._return_event(None)
        finally:
            if not blocking:
                fcntl.fcntl(fd, fcntl.F_SETFL, fl)

        if not buf:
            self._pipe_stats["empty"] += 1
            return self._return_event(None)

        if len(buf) < ev_size:
            self._pipe_stats["short"] += 1
            self._pipe_trace("short_read", avail=len(buf), force=True)
            return self._return_event(None)

        try:
            sec, usec, etype, code, value = struct.unpack("llHHi", buf)
        except Exception:
            self._pipe_stats["errors"] += 1
            self._pipe_trace("unpack_error", force=True)
            return self._return_event(None)

        self._pipe_stats["records"] += 1
        self._pipe_stats["last_etype"] = int(etype)
        self._pipe_stats["last_code"] = int(code)
        self._pipe_stats["last_value"] = int(value)

        # Approximate timestamp in milliseconds to fit the existing representation.
        timestamp = int(sec * 1000 + usec / 1000)

        if etype == EV_SYN:
            # Preserve EventController behavior: SYN is ignored and returns None.
            self._pipe_stats["syn"] += 1
            return self._return_event(None)
        if etype == EV_KEY:
            event_type = JS_EVENT_BUTTON
            number = code
        elif etype == EV_ABS:
            event_type = JS_EVENT_AXIS
            number = code
        else:
            self._pipe_stats["ignored"] += 1
            return self._return_event(None)

        # KyberPad: axis named exactly "kyberpad" becomes synthetic button events.
        if event_type & JS_EVENT_AXIS:
            axis_name = self.AXIS_MAP.get(number, f'AXIS{number}')
            aliases = list(getattr(self, "_axis_aliases", {}).get(number, [axis_name]))
            if any(isinstance(a, str) and a.lower() == "kyberpad" for a in aliases):
                # Store raw value for kyberpad decoding.
                for alias in aliases:
                    if isinstance(alias, str) and alias.lower() == "kyberpad":
                        self._axes[alias] = value
                self._handle_kyberpad_axis(timestamp, value)
                return self._return_event(self._drain_pending(invert_axes=False))

        return self._return_event(self._dispatch_event(timestamp, value, event_type, number, invert_axes=False))

class ShadowEventController(EventController):
    """In-memory controller that shadows an evdev-style event stream.

    This is intended for **server** processes (for example: broadcast_state)
    that already have a stream of EV_ABS/EV_KEY events (e.g. the same events
    they write into a FIFO via FifoSink) and want to reuse the exact same
    mapping + KyberPad decoding logic that client processes use, **without**
    opening the FIFO for reading.

    Usage:
        shadow = ShadowEventController(...)
        events = shadow.feed_evdev(EV_ABS, code, value)
    """

    def __init__(self, device_name, button_map, axis_map, *, kyberpad=None, axis_curves=None):
        super().__init__(
            device_path="(shadow)",
            device_name=device_name,
            button_map=button_map,
            axis_map=axis_map,
            reconnect_interval=0.0,
            kyberpad=kyberpad,
            axis_curves=axis_curves,
            connect=False,
        )

    def is_connected(self):
        # Shadow controllers do not have a device FD, but they are always usable.
        return True

    def feed_evdev(self, etype: int, code: int, value: int, timestamp_ms=None):
        """Feed a single evdev event and return a list of ControllerEvent objects."""
        if timestamp_ms is None:
            timestamp_ms = int(time.time() * 1000)

        out = []

        # Drain any pending synthetic events first.
        while True:
            pending = self._drain_pending(invert_axes=False)
            if pending is None:
                break
            out.append(pending)

        # Only process the event types we care about.
        if etype == EV_KEY:
            ev = self._dispatch_event(timestamp_ms, int(value), JS_EVENT_BUTTON, int(code), invert_axes=False)
            if ev is not None:
                out.append(ev)

        elif etype == EV_ABS:
            axis_name = self.AXIS_MAP.get(int(code), f"AXIS{code}")

            # KyberPad axis named exactly "kyberpad" becomes synthetic button events.
            aliases = list(getattr(self, "_axis_aliases", {}).get(int(code), [axis_name]))
            if any(isinstance(a, str) and a.lower() == "kyberpad" for a in aliases):
                for alias in aliases:
                    if isinstance(alias, str) and alias.lower() == "kyberpad":
                        self._axes[alias] = int(value)
                self._handle_kyberpad_axis(timestamp_ms, int(value))
                while True:
                    pending = self._drain_pending(invert_axes=False)
                    if pending is None:
                        break
                    out.append(pending)
            else:
                ev = self._dispatch_event(timestamp_ms, int(value), JS_EVENT_AXIS, int(code), invert_axes=False)
                if ev is not None:
                    out.append(ev)

        return out

    # Convenience aliases (mirror the sink naming)
    def feed_abs(self, code: int, value: int, timestamp_ms=None):
        return self.feed_evdev(EV_ABS, code, value, timestamp_ms=timestamp_ms)

    def feed_key(self, code: int, value: int, timestamp_ms=None):
        return self.feed_evdev(EV_KEY, code, value, timestamp_ms=timestamp_ms)


class RosJoyController(Controller):
    """Controller backed by a ROS2 sensor_msgs/msg/Joy topic."""

    def __init__(
        self,
        topic,
        device_name,
        button_map,
        axis_map,
        reconnect_interval=1.0,
        *,
        kyberpad=None,
        axis_curves=None,
    ):
        self._ros_topic = topic or "/joy"
        self._event_queue = queue.Queue() if _ROS_AVAILABLE else None
        self._ros_node = None
        self._ros_exec = None
        self._ros_thread = None
        self._ros_context = None
        self._ros_closed = False
        self._last_axes = []
        self._last_buttons = []
        super().__init__(
            f"ros2:{self._ros_topic}",
            device_name,
            button_map,
            axis_map,
            reconnect_interval,
            kyberpad=kyberpad,
            axis_curves=axis_curves,
        )

    def _connect(self):
        if not _ROS_AVAILABLE:
            logger.error("ROS2 not available; cannot use RosJoyController.")
            self.js = None
            return

        try:
            self._ros_closed = False
            self._ros_context = Context()
            init_kwargs = {"args": None, "context": self._ros_context}
            if SignalHandlerOptions is not None:
                init_kwargs["signal_handler_options"] = SignalHandlerOptions.NO
            rclpy.init(**init_kwargs)

            class _JoyNode(Node):
                pass

            node_suffix = self._ros_topic.strip("/").replace("/", "_") or "joy"
            self._ros_node = _JoyNode(f"joy_bridge_{node_suffix}", context=self._ros_context)
            self._ros_exec = SingleThreadedExecutor(context=self._ros_context)
            self._ros_exec.add_node(self._ros_node)

            def _cb(msg: Joy):
                ts_ms = int(time.time() * 1000)
                axes = list(msg.axes)
                buttons = list(msg.buttons)

                if not self._last_axes:
                    self._last_axes = axes[:]
                if not self._last_buttons:
                    self._last_buttons = buttons[:]

                for idx, val in enumerate(buttons):
                    prev = self._last_buttons[idx] if idx < len(self._last_buttons) else 0
                    if val == prev:
                        continue
                    name = self.BUTTON_MAP.get(idx, f"BTN{idx}")
                    self._buttons[name] = bool(val)
                    self._event_queue.put((ts_ms, int(bool(val)), JS_EVENT_BUTTON, idx))

                eps = 1e-4
                for idx, val in enumerate(axes):
                    prev = self._last_axes[idx] if idx < len(self._last_axes) else 0.0
                    if abs(float(val) - float(prev)) <= eps:
                        continue

                    name = self.AXIS_MAP.get(idx, f"AXIS{idx}")
                    aliases = list(getattr(self, "_axis_aliases", {}).get(idx, [name]))
                    raw = int(_clamp(float(val), -1.0, 1.0) * 32767)
                    for alias in aliases:
                        self._axes[alias] = -raw
                    self._event_queue.put((ts_ms, raw, JS_EVENT_AXIS, idx))

                self._last_axes = axes[:]
                self._last_buttons = buttons[:]

            self._ros_node.create_subscription(Joy, self._ros_topic, _cb, 10)

            def _spin():
                try:
                    while self._ros_context.ok() and not self._ros_closed:
                        self._ros_exec.spin_once(timeout_sec=0.1)
                except Exception as e:
                    if not self._ros_closed:
                        logger.error(f"ROS executor error: {e}")

            self._ros_thread = threading.Thread(target=_spin, daemon=True)
            self._ros_thread.start()

            class _Sentinel:
                def fileno(self):
                    return 0

                def close(self):
                    pass

            self.js = _Sentinel()
            self.name = self.device_name
            logger.info(f"Connected to ROS Joy on topic {self._ros_topic}")

        except Exception as e:
            logger.error(f"Failed to init ROS Joy: {e}")
            self._close_ros_handles()
            self.js = None

    def is_connected(self):
        return (
            self.js is not None
            and _ROS_AVAILABLE
            and self._ros_context is not None
            and self._ros_context.ok()
        )

    def _try_reconnect(self):
        if not self.is_connected():
            self._connect()

    def read_event(self, blocking=True):
        if not self.is_connected():
            self._try_reconnect()
            if not self.is_connected():
                return None

        try:
            ts_ms, value, event_type, number = self._event_queue.get(
                block=blocking,
                timeout=0.0 if not blocking else None,
            )
        except queue.Empty:
            return None

        event = ControllerEvent(self, ts_ms, value, event_type, number)

        if event_type & JS_EVENT_BUTTON and value == 0 and event.name in self._ignore_releases:
            self._ignore_releases.remove(event.name)
            return None

        gesture = None
        if self._gesture_trigger and event_type & JS_EVENT_BUTTON:
            gesture = self._update_gesture(event)
        event.gesture = gesture

        if gesture and event_type & JS_EVENT_BUTTON:
            event.name = gesture
            event.value = None
            return event

        if self._gesture_start:
            return None

        return event

    def _close_ros_handles(self):
        self._ros_closed = True
        context = self._ros_context
        try:
            if context is not None and context.ok():
                context.shutdown()
        except Exception:
            pass
        try:
            if self._ros_exec:
                self._ros_exec.shutdown()
        except Exception:
            pass
        try:
            if self._ros_thread and self._ros_thread.is_alive():
                self._ros_thread.join(timeout=1.0)
        except Exception:
            pass
        try:
            if self._ros_exec and self._ros_node:
                try:
                    self._ros_exec.remove_node(self._ros_node)
                except Exception:
                    pass
            if self._ros_node:
                self._ros_node.destroy_node()
        except Exception:
            pass
        self._ros_node = None
        self._ros_exec = None
        self._ros_thread = None
        self._ros_context = None

    def close(self):
        self._close_ros_handles()
        self.js = None


