def discover(*, include_virtual=True):
    """Discover controllers on /dev/input/js* and /dev/input/event*.

    ``include_virtual=False`` omits the PuddleDuckStick and SteamDuckStick
    FIFOs.  This is used by the body trigger watcher because broadcast_state
    already observes those virtual controllers at the point where it emits
    their events.
    """
    instances = []
    seen_names = set()

    # Scan /dev/input/js* devices
    for path in glob.glob('/dev/input/js*'):
        try:
            fd = open(path, 'rb')
            buf = array.array('b', [0]*128)
            fcntl.ioctl(fd, JSIOCGNAME + (len(buf)<<16), buf)
            name = buf.tobytes().rstrip(b'\x00').decode('utf-8', 'replace')
            fd.close()
        except Exception:
            continue

        if name in seen_names:
            continue

        if name in _controller_defs:
            d = _controller_defs[name]
            ctrl = Controller(
                path,
                d['name'],
                d['buttons'],
                d['axes'],
                kyberpad=d.get('kyberpad'),
                axis_curves=d.get('axis_curves') or {},
                invert_js_axes=d.get('invert_js_axes', True),
            )
            if d['gestures'] and d['gesture_trigger']:
                ctrl.configure_gestures(d['gesture_trigger'], d['gestures'])
                logger.info(f"Configured gestures for {d['name']}")
            instances.append(ctrl)
            seen_names.add(name)
        elif name in _controller_registry:
            instances.append(_controller_registry[name](path))
            seen_names.add(name)
        else:
            logger.warning(f"Skipping unsupported controller '{name}' at {path}")
            # print(_controller_defs)

    # Prefer /dev/input/event* (evdev)
    for path in glob.glob('/dev/input/event*'):
        try:
            name = _get_event_device_name(path)
        except Exception:
            continue

        # If we already attached via js* for this device name, skip the event node
        if name in seen_names:
            continue

        if name in _controller_defs:
            d = _controller_defs[name]
            ctrl = EventController(
                path,
                d['name'],
                d['buttons'],
                d['axes'],
                kyberpad=d.get('kyberpad'),
                axis_curves=d.get('axis_curves') or {},
            )
            if d['gestures'] and d['gesture_trigger']:
                ctrl.configure_gestures(d['gesture_trigger'], d['gestures'])
                logger.info(f"Configured gestures for {d['name']} (event device)")
            instances.append(ctrl)
            seen_names.add(name)
        elif name in _controller_registry:
            # Built-in controllers are written for js*; skip for now.
            logger.warning(
                f"Built-in controller '{name}' found at event device {path}, "
                f"but only js* is supported for this built-in. "
                f"Add a YAML mapping if you want to use the event device."
            )
        else:
            logger.warning(f"Skipping Unsupported controller '{name}' at {path} (event device)")
            # print(_controller_defs)

    name = "PuddleDuckStick"
    if include_virtual and (
        name not in seen_names
        and os.path.exists(PUDDLE_FIFO_PATH)
        and stat.S_ISFIFO(os.stat(PUDDLE_FIFO_PATH).st_mode)
    ):
        if name in _controller_defs:
            d = _controller_defs[name]
            ctrl = PipeController(
                PUDDLE_FIFO_PATH,
                d['name'],
                d['buttons'],
                d['axes'],
                kyberpad=d.get('kyberpad'),
                axis_curves=d.get('axis_curves') or {},
            )
            if d['gestures'] and d['gesture_trigger']:
                ctrl.configure_gestures(d['gesture_trigger'], d['gestures'])
            instances.append(ctrl)
            seen_names.add(name)
        else:
            logger.warning(f"No controller definition for virtual FIFO '{name}'")


    # Optional second virtual FIFO: SteamDuckStick (TouchOSC gamepad over RF)
    name = "SteamDuckStick"
    if include_virtual and (
        name not in seen_names
        and os.path.exists(STEAM_FIFO_PATH)
        and stat.S_ISFIFO(os.stat(STEAM_FIFO_PATH).st_mode)
    ):
        if name in _controller_defs:
            d = _controller_defs[name]
            ctrl = PipeController(
                STEAM_FIFO_PATH,
                d['name'],
                d['buttons'],
                d['axes'],
                kyberpad=d.get('kyberpad'),
                axis_curves=d.get('axis_curves') or {},
            )
            if d['gestures'] and d['gesture_trigger']:
                ctrl.configure_gestures(d['gesture_trigger'], d['gestures'])
            instances.append(ctrl)
            seen_names.add(name)
        else:
            logger.warning(f"No controller definition for virtual FIFO '{name}'")

    # ROS Joy controllers defined in YAML (device "ROS Joy" or any ros_topic).
    # This intentionally is not gated by include_virtual; that flag only omits
    # FIFO readers used by the body trigger watcher.
    for device, d in _controller_defs.items():
        if device in seen_names:
            continue
        if device != "ROS Joy" and not d.get("ros_topic"):
            continue

        topic = d.get("ros_topic") or "/joy"
        if not _ROS_AVAILABLE:
            logger.error(f"ROS Joy '{d['name']}' requested but ROS2 not available.")
            continue

        ctrl = RosJoyController(
            topic,
            d["name"] or "ROS Joy",
            d["buttons"],
            d["axes"],
            kyberpad=d.get("kyberpad"),
            axis_curves=d.get("axis_curves") or {},
        )
        if d["gestures"] and d["gesture_trigger"]:
            ctrl.configure_gestures(d["gesture_trigger"], d["gestures"])
            logger.info(f"Configured gestures for {d['name']}")
        instances.append(ctrl)
        seen_names.add(device)

    return instances


def load_default_controller_definitions():
    BUILTIN_CONTROLLER_PATH = Path(__file__).parent / 'controllers'
    print(f"BUILTIN_CONTROLLER_PATH: {BUILTIN_CONTROLLER_PATH}")
    load_controller_definitions(BUILTIN_CONTROLLER_PATH)
    load_controller_definitions(HOME_DIR / 'controllers')


class PuddleJoy:
    """Convenience namespace for discovery/definition-loading."""

    @classmethod
    def discover(cls, *, include_virtual=True):
        return discover(include_virtual=include_virtual)

    @classmethod
    def load_default_controller_definitions(cls):
        return load_default_controller_definitions()

    @classmethod
    def load_controller_definitions(cls, dir_path):
        """Load additional controller YAML definitions from a directory."""
        return load_controller_definitions(dir_path)

    @classmethod
    def get_controller_definition(cls, device_name):
        return get_controller_definition(device_name)

    @classmethod
    def get_controller_definition_for_file(cls, filename, *, index=0):
        return get_controller_definition_for_file(filename, index=index)

    @classmethod
    def get_virtual_osc_maps(cls, device: str):
        """Return inverted OSC-address maps for a controller definition.

        For a given controller `device` name, look for axis/button mappings whose
        mapped *name* starts with '/' (treated as an OSC address), and return:

            (osc_axes, osc_buttons)

        where:
            osc_axes    = {"/some/osc/address": abs_code_int, ...}
            osc_buttons = {"/some/osc/address": key_code_int, ...}

        This is useful for taking inbound OSC messages and injecting them as
        EV_ABS / EV_KEY events using synthetic codes from the controller YAML.
        """
        d = _controller_defs.get(device)
        if not d:
            raise KeyError(f"No controller definition loaded for {device!r}")

        axes = d.get("axes") or {}
        buttons = d.get("buttons") or {}

        osc_axes = {}
        for code, name in axes.items():
            if isinstance(name, str) and name.startswith("/"):
                osc_axes[str(name)] = int(code)

        osc_buttons = {}
        for code, name in buttons.items():
            if isinstance(name, str) and name.startswith("/"):
                osc_buttons[str(name)] = int(code)

        return osc_axes, osc_buttons

    @classmethod
    def create_shadow(cls, device: str):
        """Create a ShadowEventController from a YAML-loaded controller definition.

        This does **not** call `discover()` and does not open any devices.
        It simply instantiates an in-memory controller that can be fed with
        evdev-style events (EV_ABS/EV_KEY) and will produce ControllerEvent
        objects (including KyberPad synthetic button events).
        """
        d = _controller_defs.get(device)
        if not d:
            raise KeyError(f"No controller definition loaded for {device!r}")
        return ShadowEventController(
            device_name=d.get('name') or device,
            button_map=d.get('buttons') or {},
            axis_map=d.get('axes') or {},
            kyberpad=d.get('kyberpad') or {},
            axis_curves=d.get('axis_curves') or {},
        )

if __name__ == '__main__':
    PuddleJoy.load_default_controller_definitions()
    controllers = PuddleJoy.discover()
    if not controllers:
        logger.error("No controllers found. Exiting.")
        exit(1)

    for c in controllers:
        c.set_scale(-1.0, 1.0)

    logger.info("Listening for events...")

    # --- constants / gains (copied from sim-style logic) ---
    TORSO_ONSET      = 0.60   # start adding torso when |gaze| > 0.60
    TORSO_GAIN_PITCH = 1.00
    TORSO_GAIN_YAW   = 1.00
    TORSO_GAIN_ROLL  = 1.00
    DEADZONE = 0.015
    ALPHA    = 0.001           # smoothing for commands
    EPS      = 1e-4

    # How quickly LB/RB drives lateral velocity per loop
    LIN_VEL_Y_RATE  = 0.02    # tweak as needed
    LIN_VEL_Y_DECAY = 0.9     # how fast it relaxes back to zero

    # Height stepping via DPad DY (virtual axis)
    HEIGHT_STEP = 0.25        # 9 discrete levels in [-1, 1]

    # ---------------------------
    # Trunk wiggle
    # Only when not moving (lin/ang commands ~ 0)
    # ---------------------------
    WIGGLE_FREQ = 2   # Hz
    TRUNK_WIGGLE_AMP  = 1.0   # amplitude in command units [-1, 1]
    HEAD_WIGGLE_AMP  = 0.5   # amplitude in command units [-1, 1]
    MOVE_EPS    = 1e-3  # how close to "zero movement" we require

    def torso_blend_component(v, gain, onset=TORSO_ONSET):
        a = abs(v)
        if a <= onset:
            return 0.0
        t = (a - onset) / (1.0 - onset)   # ramp 0..1
        return gain * t * (v / a)         # keep sign of v

    def dz(v, d=DEADZONE):
        return 0.0 if abs(v) < d else v

    def apply_curve(v, exponent=1.5):
        return math.copysign(abs(v) ** exponent, v)

    def shaped(v):
        return max(-1.0, min(1.0, apply_curve(v)))

    def smooth(prev, raw, min_val=-1.0, max_val=1.0, eps=EPS):
        upd = prev*(1.0 - ALPHA) + raw*ALPHA
        upd = max(min_val, min(max_val, upd))
        if abs(upd) < eps:
            upd = 0.0
        return upd

    def clamp(v, lo, hi):
        return max(lo, min(hi, v))

    # --- state ---
    commands = [0.0] * 11  # 0..10 like in simulator mapping

    # Per-controller transient state for derived/virtual inputs.
    # Stored per-controller so switching devices mid-run doesn't break edge detectors.
    ctrl_state = {
        c: {
            "prev_dy": 0.0,
            "height_state": 0.0,
            "lin_vel_y_state": 0.0,
            "last_axis": {},     # axis_name -> last scaled value (for activity detection)
            "last_activity": 0.0,
        }
        for c in controllers
    }

    last_event = {c: None for c in controllers}
    active_controller = None

    trunk_wiggle_phase = 0.0
    trunk_wiggle_time  = time.time()

    counter = 0
    strafe_src = ""

    # Activity / switching heuristics
    AXIS_ACTIVITY_EPS = 0.02   # ignore tiny axis jitter when picking active controller

    def axis_present(ev, name: str) -> bool:
        return name in ev.controller._axes

    def trigger_to_01(v: float) -> float:
        # Accept both [-1, 1] and [0, 1] conventions.
        return (v + 1.0) / 2.0 if v < 0.0 else v

    def update_height_virtual(ev, st):
        """
        Update stepped height from either:
          - DPad DY axis edges
          - 'taller' / 'smaller' button press edges
        """
        # --- Button presses (edge-detected) ---
        if ev.was_pressed("taller"):
            st["height_state"] = clamp(st["height_state"] + HEIGHT_STEP, -1.0, 1.0)
        if ev.was_pressed("smaller"):
            st["height_state"] = clamp(st["height_state"] - HEIGHT_STEP, -1.0, 1.0)

        # --- DPad DY edges (existing behavior) ---
        dy = ev.get_axis("DY")
        prev = st["prev_dy"]

        if dy > 0.5 and prev <= 0.5:
            st["height_state"] = clamp(st["height_state"] + HEIGHT_STEP, -1.0, 1.0)
        elif dy < -0.5 and prev >= -0.5:
            st["height_state"] = clamp(st["height_state"] - HEIGHT_STEP, -1.0, 1.0)

        st["prev_dy"] = dy
        return st["height_state"]

    def derive_lin_vel_y(ev, st):
        """
        Lateral velocity (strafe) source priority:
          1) Dedicated axis:   'lin_vel_y'
          2) Triggers:         RT - LT   (common on PS-style)
          3) Fallback synth:   integrate LB/RB
        """
        if axis_present(ev, "lin_vel_y"):
            return ev.get_axis("lin_vel_y"), "axis"

        if axis_present(ev, "LT") and axis_present(ev, "RT"):
            lt = trigger_to_01(ev.get_axis("LT"))
            rt = trigger_to_01(ev.get_axis("RT"))
            return clamp(rt - lt, -1.0, 1.0), "triggers"

        # last resort: integrate from LB/RB
        lb = ev.is_pressed("LB")
        rb = ev.is_pressed("RB")

        if lb and not rb:
            st["lin_vel_y_state"] -= LIN_VEL_Y_RATE
        elif rb and not lb:
            st["lin_vel_y_state"] += LIN_VEL_Y_RATE
        else:
            st["lin_vel_y_state"] *= LIN_VEL_Y_DECAY

        st["lin_vel_y_state"] = clamp(st["lin_vel_y_state"], -1.0, 1.0)
        return st["lin_vel_y_state"], "lb_rb"

    def derive_height(ev, st):
        # Prefer a real height axis when available; otherwise use stepped DY.
        if axis_present(ev, "height"):
            return ev.get_axis("height"), True  # analog height
        return update_height_virtual(ev, st), False  # stepped height

    def is_meaningful_event(ev, st) -> bool:
        """
        Used only for selecting which controller is "active".
        Button events are always meaningful.
        Axis events are meaningful only if they changed by >= AXIS_ACTIVITY_EPS.
        """
        if ev.is_button_event():
            return True

        if ev.is_axis_event():
            name = ev.name
            v = ev.get_axis(name)

            if name not in st["last_axis"]:
                st["last_axis"][name] = v
                return True

            prev = st["last_axis"][name]
            st["last_axis"][name] = v
            return abs(v - prev) >= AXIS_ACTIVITY_EPS

        return False

    def pick_active_controller(current_active):
        # If the current active controller dropped, release it.
        if current_active is not None and not current_active.is_connected():
            current_active = None

        best = current_active
        best_t = ctrl_state[current_active]["last_activity"] if current_active else -1.0

        for c in controllers:
            if not c.is_connected():
                continue
            t = ctrl_state[c]["last_activity"]
            if t > best_t:
                best_t = t
                best = c
        return best

    def on_activate(ev, st):
        """
        When switching to a controller that relies on virtual/stepped inputs,
        seed its internal state from the *current* smoothed outputs so you don't
        get a jump when you switch devices.
        """
        if not axis_present(ev, "height"):
            st["height_state"] = commands[3]
            st["prev_dy"] = ev.get_axis("DY")

        # Only relevant if we end up using LB/RB synth strafe.
        if (not axis_present(ev, "lin_vel_y")) and (not (axis_present(ev, "LT") and axis_present(ev, "RT"))):
            st["lin_vel_y_state"] = commands[1]

    try:
        while True:
            now = time.time()

            # 1) Poll all controllers (non-blocking) and remember the last event per controller.
            polled = []
            for c in controllers:
                # Drain a handful of queued events so the "state" catches up quickly.
                ev = c.read_event(blocking=False)
                if ev is not None:
                    polled.append(ev)
                    last_event[c] = ev

                    st = ctrl_state[c]
                    if is_meaningful_event(ev, st):
                        st["last_activity"] = now

            # 2) Pick which controller is currently active (most recently used).
            active_controller = None
            prev_active = active_controller
            active_controller = pick_active_controller(active_controller)

            if active_controller is None:
                continue

            joy_ev = last_event.get(active_controller)
            if joy_ev is None:
                continue

            if active_controller is not prev_active:
                on_activate(joy_ev, ctrl_state[active_controller])

            st = ctrl_state[active_controller]

            # 3) Read logical inputs (one unified pipeline)
            lin_vel_x_raw = joy_ev.get_axis("lin_vel_x")
            ang_vel_raw   = joy_ev.get_axis("ang_vel")

            head_pitch_raw = joy_ev.get_axis("head_pitch")
            head_yaw_raw   = joy_ev.get_axis("head_yaw")

            # Head roll: prefer a dedicated axis if present, otherwise 0.
            head_roll_raw = joy_ev.get_axis("head_roll") if axis_present(joy_ev, "head_roll") else 0.0

            # Lateral velocity + height may be "virtual"
            lin_vel_y_raw, strafe_src = derive_lin_vel_y(joy_ev, st)
            height_raw, height_is_analog = derive_height(joy_ev, st)

            # 4) Torso assist follows raw head (before pitch-inversion blend)
            trunk_pitch_raw = torso_blend_component(head_pitch_raw, TORSO_GAIN_PITCH)
            trunk_yaw_raw   = torso_blend_component(head_yaw_raw,   TORSO_GAIN_YAW)
            trunk_roll_raw  = torso_blend_component(head_roll_raw,  TORSO_GAIN_ROLL)

            # 5) Deadzone + response curve
            lin_vel_x = shaped(dz(lin_vel_x_raw))
            lin_vel_y = shaped(dz(lin_vel_y_raw))
            ang_vel   = shaped(dz(ang_vel_raw))

            # Height: only shape analog height; keep stepped height linear.
            height = shaped(dz(height_raw)) if height_is_analog else height_raw

            neck_pitch = shaped(dz(head_pitch_raw))
            head_yaw   = shaped(dz(head_yaw_raw))
            head_roll  = shaped(dz(head_roll_raw))

            trunk_pitch = shaped(dz(trunk_pitch_raw))
            trunk_yaw   = shaped(dz(trunk_yaw_raw))
            trunk_roll  = shaped(dz(trunk_roll_raw))

            # 6) Neck/head pitch blend (same→invert blend)
            THRESH = -0.4
            WIDTH  = 0.3
            low  = THRESH - WIDTH
            high = THRESH + WIDTH

            if neck_pitch <= low:
                t = 0.0
            elif neck_pitch >= high:
                t = 1.0
            else:
                t = (neck_pitch - low) / (high - low)

            head_pitch = (1.0 - t) * neck_pitch + t * (-neck_pitch)

            # 7) Idle wiggle (only when not moving)
            if joy_ev.is_pressed("RS_B") and (
                abs(lin_vel_x) < MOVE_EPS and
                abs(lin_vel_y) < MOVE_EPS and
                abs(ang_vel)   < MOVE_EPS
            ):
                dt = now - trunk_wiggle_time
                trunk_wiggle_time = now

                trunk_wiggle_phase += 2.0 * math.pi * WIGGLE_FREQ * dt
                trunk_yaw = TRUNK_WIGGLE_AMP * math.sin(trunk_wiggle_phase)
                head_yaw  = HEAD_WIGGLE_AMP  * math.sin(trunk_wiggle_phase)
                head_roll = head_yaw
            else:
                trunk_wiggle_time = now

            # 8) Smooth into command vector (single smoothing stage for head now)
            commands[0]  = smooth(commands[0],  lin_vel_x,    -1.0, 1.0)
            commands[1]  = smooth(commands[1],  lin_vel_y,    -1.0, 1.0)
            commands[2]  = smooth(commands[2],  ang_vel,      -1.0, 1.0)
            commands[3]  = smooth(commands[3],  height,       -1.0, 1.0)
            commands[4]  = smooth(commands[4],  neck_pitch,   -1.0, 1.0)

            commands[5]  = smooth(commands[5],  head_pitch,   -1.0, 1.0)
            commands[6]  = smooth(commands[6],  head_yaw,     -1.0, 1.0)
            commands[7]  = smooth(commands[7],  head_roll,    -1.0, 1.0)

            commands[8]  = smooth(commands[8], -trunk_pitch,  -1.0, 1.0)
            commands[9]  = smooth(commands[9], -trunk_yaw,    -1.0, 1.0)
            commands[10] = smooth(commands[10], trunk_roll,   -1.0, 1.0)

            # 9) Safety clamp for primary commands
            commands[0] = clamp(commands[0], -1.0, 1.0)
            commands[1] = clamp(commands[1], -1.0, 1.0)
            commands[2] = clamp(commands[2], -1.0, 1.0)

            # Print every button press/release using its YAML-mapped name.
            for ev in polled:
                if ev.controller is not active_controller:
                    continue

                if ev.is_button_event():
                    action = "pressed" if ev.value else "released"

                    # Clear the live status line before printing the event.
                    sys.stdout.write("\r\033[K")
                    print(
                        f"{active_controller.device_name}: "
                        f"button {ev.number} {ev.name} {action}",
                        flush=True,
                    )
                    
            # 10) Button handling (events from active controller only)
            for ev in polled:
                if ev.controller is not active_controller:
                    continue
                if ev.was_pressed("Select"):
                    print("Select")
                if ev.was_pressed("Start"):
                    print("Start")
                if ev.was_pressed("Power"):
                    print("Power")
                if ev.was_pressed("LS_B"):
                    print("LS_B")
                if ev.was_pressed("RS_B"):
                    print("RS_B")
                if ev.was_pressed("A"):
                    print("A")
                if ev.was_pressed("X"):
                    print("X")
                if ev.was_pressed("Y"):
                    print("Y")
                if ev.was_pressed("LB"):
                    print("LB")
                if ev.was_pressed("RB"):
                    print("RB")

            # print(
            #     f"[{counter}][{strafe_src}] {active_controller.device_name}:{commands}                                          ",
            # )
            sys.stdout.write(
                f"\r[{counter}][{strafe_src}] {active_controller.device_name}:{commands}                                          ",
            )
            sys.stdout.flush()
            counter += 1

    except KeyboardInterrupt:
        logger.info("Shutting down.")
    finally:
        for c in controllers:
            c.close()
